const express = require('express');
const { ethers } = require('ethers');
const db = require('../db');

const app = express();
app.use(express.json());
const signer = new ethers.Wallet(process.env.DECRYPTION_AUTHORITY_KEY);

app.post('/api/vault/ipfs/decrypt-grant', async (req, res) => {
  const { cid, recipientDid } = req.body;

  if (!cid || !recipientDid) {
    return res.status(400).json({ error: 'cid and recipientDid are required' });
  }

  // Verify caller ownership or access grant on target encrypted CID
  const grant = await db('vault_access_grants')
    .join('vault_files', 'vault_access_grants.file_id', '=', 'vault_files.id')
    .where({
      'vault_files.ipfs_cid': cid,
      'vault_access_grants.user_id': req.user.id
    })
    .first();

  if (!grant) {
    return res.status(403).json({ error: 'Access denied: No decryption entitlement for CID' });
  }

  const messageHash = ethers.solidityPackedKeccak256(
    ['string', 'string', 'uint256'],
    [cid, recipientDid, Math.floor(Date.now() / 1000) + 3600]
  );

  const signature = await signer.signMessage(ethers.getBytes(messageHash));

  return res.json({
    cid,
    recipientDid,
    signature,
    expiresAt: Math.floor(Date.now() / 1000) + 3600
  });
});

module.exports = app;
